	@Test
	void fallbackRowsRespectLedgerAndStreamTheRefusedTail() {
		LmdbQueryMemoryManager manager = LmdbQueryMemoryManager.process();
		long initialUsed = manager.usedBytes();
		assertThat(manager.perQueryMaxBytes()).isGreaterThanOrEqualTo(AVAILABLE_BYTES);
		long occupied = manager.maxBytes() - initialUsed - AVAILABLE_BYTES;
		assertThat(occupied).isPositive();
		List<LmdbQueryMemoryManager.QueryLedger> blockers = new ArrayList<>();
		try {
			while (occupied > 0) {
				LmdbQueryMemoryManager.QueryLedger blocker = manager.openQuery();
				blockers.add(blocker);
				long amount = Math.min(occupied, manager.perQueryMaxBytes());
				assertThat(blocker.reserve(amount, null)).isNotNull();
				occupied -= amount;
			}
			long blockedUsed = manager.usedBytes();
			assertThat(manager.maxBytes() - blockedUsed).isEqualTo(AVAILABLE_BYTES);
			for (boolean closeEarly : new boolean[] { false, true }) {
				fallbackOpens.set(0);
				fallbackCloses.set(0);
				CountingOuter outer = new CountingOuter();
				BatchCorrelatedJoinProvider.BatchCorrelationRequest request = request(outer,
						BatchCorrelatedJoinProvider.Mode.LEFT, condition());
				try (CloseableIteration<BindingSet> rows = LmdbNativeAccumulateJoin.INSTANCE.tryBatchJoin(request,
						nativeFragment)) {
					assertThat(rows.hasNext()).isTrue();
					assertThat(manager.usedBytes()).as("retained rows consume the available budget")
							.isEqualTo(manager.maxBytes());
					assertThat((long) outer.read).as("bounded retained rows before the first result")
							.isLessThanOrEqualTo(AVAILABLE_BYTES / BYTES_PER_RETAINED_ROW);
					if (closeEarly) {
						assertResult(rows.next(), 0);
					} else {
						for (int index = 0; index < ROWS; index++) {
							assertThat(rows.hasNext()).as("row %s", index).isTrue();
							assertResult(rows.next(), index);
						}
						assertThat(rows.hasNext()).isFalse();
						assertThat(outer.read).isEqualTo(ROWS);
						assertThat(fallbackOpens).hasValue(ROWS);
					}
				}
				assertThat(outer.closes).isEqualTo(1);
				assertThat(fallbackCloses).hasValue(fallbackOpens.get());
				assertThat(manager.usedBytes()).as("all batch reservations released").isEqualTo(blockedUsed);
			}
		} finally {
			blockers.forEach(LmdbQueryMemoryManager.QueryLedger::close);
		}
		assertThat(manager.usedBytes()).isEqualTo(initialUsed);
	}

